cat > /tmp/test_fully_shipped.py <<'EOF'
import pandas as pd
from shipreport.status import fully_shipped

def test_fully_shipped():
    # Case 1: All shipped
    orders1 = pd.DataFrame({
        "region": ["north", "north"],
        "product": ["basic", "basic"],
        "shipped": [True, True]
    })
    assert fully_shipped(orders1) == {("north", "basic"): True}

    # Case 2: Some not shipped
    orders2 = pd.DataFrame({
        "region": ["north", "north"],
        "product": ["basic", "basic"],
        "shipped": [True, False]
    })
    assert fully_shipped(orders2) == {("north", "basic"): False}

    # Case 3: Multiple pairs
    orders3 = pd.DataFrame({
        "region": ["north", "north", "south"],
        "product": ["basic", "basic", "pro"],
        "shipped": [True, True, False]
    })
    assert fully_shipped(orders3) == {("north", "basic"): True, ("south", "pro"): False}

    # Case 4: Empty dataframe
    orders4 = pd.DataFrame(columns=["region", "product", "shipped"])
    assert fully_shipped(orders4) == {}

    print("All tests passed!")

if __name__ == "__main__":
    test_fully_shipped()
EOF
